  ('en', 'admin.reminders.wizard.whatIs1', 'A short series of messages that goes out by itself when something happens, before something happens, or when something didn''t happen in time.'),
  ('he', 'admin.reminders.wizard.whatIs1', U&'\05E8\05E6\05E3 \05E7\05E6\05E8 \05E9\05DC \05D4\05D5\05D3\05E2\05D5\05EA \05E9\05D9\05D5\05E6\05D0 \05DC\05D1\05D3 \05DB\05E9\05DE\05E9\05D4\05D5 \05E7\05D5\05E8\05D4, \05DC\05E4\05E0\05D9 \05E9\05DE\05E9\05D4\05D5 \05E7\05D5\05E8\05D4, \05D0\05D5 \05DB\05E9\05DE\05E9\05D4\05D5 \05DC\05D0 \05E7\05E8\05D4 \05D1\05D6\05DE\05DF.'),
  ('en', 'admin.reminders.wizard.whatIs2', 'It stops by itself as soon as the matter is sorted.'),
