  ('en', 'admin.reminders.wizard.yesOnText', 'From the moment you save, every new case starts the reminder'),
  ('he', 'admin.reminders.wizard.yesOnText', U&'\05DE\05D4\05E8\05D2\05E2 \05E9\05E9\05D5\05DE\05E8\05D9\05DD, \05DB\05DC \05DE\05E7\05E8\05D4 \05D7\05D3\05E9 \05DE\05EA\05D7\05D9\05DC \05D0\05EA \05D4\05EA\05D6\05DB\05D5\05E8\05EA'),
  ('en', 'emails.triggers.movingNote', 'Email triggers are moving into Automatic reminders, where every message follows the client''s update settings. Turning on ''Before a live meeting'' or ''Recording is ready'' there switches the matching trigger here off, so nobody gets two.'),
  ('he', 'emails.triggers.movingNote', U&'\05D8\05E8\05D9\05D2\05E8\05D9\05DD \05E9\05DC \05D0\05D9\05DE\05D9\05D9\05DC \05E2\05D5\05D1\05E8\05D9\05DD \05DC\05EA\05D6\05DB\05D5\05E8\05D5\05EA \05D0\05D5\05D8\05D5\05DE\05D8\05D9\05D5\05EA, \05E9\05DD \05DB\05DC \05D4\05D5\05D3\05E2\05D4 \05D9\05D5\05E6\05D0\05EA \05DC\05E4\05D9 \05D4\05D2\05D3\05E8\05D5\05EA \05D4\05E2\05D3\05DB\05D5\05E0\05D9\05DD \05E9\05DC \05D4\05DC\05E7\05D5\05D7. \05D4\05E4\05E2\05DC\05D4 \05E9\05DC ''\05EA\05D6\05DB\05D5\05E8\05EA \05DC\05E4\05E0\05D9 \05DE\05E4\05D2\05E9 \05D7\05D9'' \05D0\05D5 ''\05D4\05D4\05E7\05DC\05D8\05D4 \05E2\05DC\05EA\05D4'' \05E9\05DD \05DE\05DB\05D1\05D4 \05DB\05D0\05DF \05D0\05EA \05D4\05D8\05E8\05D9\05D2\05E8 \05D4\05DE\05EA\05D0\05D9\05DD, \05DB\05D3\05D9 \05E9\05D0\05E3 \05D0\05D7\05D3 \05DC\05D0 \05D9\05E7\05D1\05DC \05E4\05E2\05DE\05D9\05D9\05DD.'),
  ('en', 'emails.triggers.openReminders', 'Open Automatic reminders'),
  ('he', 'emails.triggers.openReminders', U&'\05DC\05EA\05D6\05DB\05D5\05E8\05D5\05EA \05D4\05D0\05D5\05D8\05D5\05DE\05D8\05D9\05D5\05EA')
